using System.Text.Json;
internal static class AggregateChecks
{
 internal static async Task Run(string output){var checks=new List<string>();void Check(bool v,string s){if(!v)throw new Exception(s);checks.Add(s);Console.WriteLine("PASS "+s);}var q=await QuoteFixture.Create();var actor=SimPersonaCatalog.Get("ray")!;
 var line=(await q.Store.ReadQuoteSource(q.Id,actor)).Lines[0];var d=await q.Store.RenderQuoteCopy(q.Id,new(Guid.NewGuid().ToString(),[new(line.RfqId,line.EstimateId!,line.Token!)]),actor);var c=await q.Store.SaveQuoteCopy(q.Id,new(Guid.NewGuid().ToString(),d.Id,d.Token),actor);var first=await q.Store.RecordManualQuoteSend(q.Id,c.Id,new(Guid.NewGuid().ToString(),c.Token!,c.Sha256),actor);
 await q.Complete(1);await q.Complete(2);var source=await q.Store.ReadQuoteSource(q.Id,actor);var selections=source.Lines.Select(l=>new SimQuoteSelection(l.RfqId,l.EstimateId!,l.Token!)).ToArray();var basis=new[]{new SimQuoteRevisionBasis(first.Id,first.Token!,first.Sha256)};d=await q.Store.RenderQuoteCopy(q.Id,new(Guid.NewGuid().ToString(),selections,RevisionOf:basis),actor);c=await q.Store.SaveQuoteCopy(q.Id,new(Guid.NewGuid().ToString(),d.Id,d.Token),actor);await q.Store.RecordManualQuoteSend(q.Id,c.Id,new(Guid.NewGuid().ToString(),c.Token!,c.Sha256),actor);
 var queue=JsonSerializer.SerializeToElement(await q.Store.ReadRfqCommercialQueue(),Fixture.Json);var group=queue.GetProperty("parentGroups")[0];Check(group.GetProperty("manuallySentLines").GetInt32()==3&&group.GetProperty("manualSendStatus").GetString()=="ALL_SENT_MANUALLY","Combined revised copy advances manual-send parent from partial1/3 to full3/3 exactly once");Check(queue.GetProperty("items").EnumerateArray().All(i=>i.GetProperty("status").GetString()=="Sent manually"&&i.GetProperty("commercial").GetProperty("status").GetString()=="OPEN"),"Full manual-send aggregate creates no formal commercial/issuance/order state");Check(q.F.SourcesUnchanged()&&await File.ReadAllTextAsync(Path.Combine(q.F.Root,"material-part-requests-v1",q.Kept.Id+".json"))==q.KeptBytes,"Combined-copy status retains source packages and existing technical allowance evidence");await File.WriteAllTextAsync(Path.Combine(output,"AGGREGATE-RESULTS.json"),JsonSerializer.Serialize(new{passed=checks.Count,checks,fixtureOnly=true,actualBusinessWrites=0},new JsonSerializerOptions{WriteIndented=true}));}
}
